from django.utils import timezone


FECHA_ANTERIOR = re.compile(r"actualizado el (\d{1,2})/(\d{1,2})/(\d{2,4})")


def rellenar_datos(apps, schema_editor):
    """Completa lo nuevo con lo que ya existía en la base de datos."""
    Producto = apps.get_model("inventario", "Producto")
    Reparacion = apps.get_model("inventario", "Reparacion")
    ReparacionEquipo = apps.get_model("inventario", "ReparacionEquipo")
    ReparacionPieza = apps.get_model("inventario", "ReparacionPieza")

    # 1) Fecha del precio de venta: la del sistema anterior si el producto la trae en la descripción
    #    ("... actualizado el 15/07/26"); si no, la fecha en que se creó el producto.
    for p in Producto.objects.filter(precio_venta_actualizado__isnull=True).iterator():
        fecha = p.creado
        m = FECHA_ANTERIOR.search(p.descripcion or "")
        if m:
            d, mes, a = int(m.group(1)), int(m.group(2)), int(m.group(3))
            try:
                fecha = timezone.make_aware(datetime(a + 2000 if a < 100 else a, mes, d, 12, 0))
            except ValueError:
                pass
        Producto.objects.filter(pk=p.pk).update(precio_venta_actualizado=fecha)

    # 2) Las reparaciones que ya existían pasan a tener un equipo con su falla
    for r in Reparacion.objects.filter(equipos__isnull=True).iterator():
        ReparacionEquipo.objects.create(reparacion=r, modelo=r.equipo, falla=r.trabajo)

    # 3) Las piezas ya usadas guardan el precio de compra actual como costo
    for pz in ReparacionPieza.objects.select_related("producto").iterator():
        ReparacionPieza.objects.filter(pk=pz.pk).update(costo_unitario=pz.producto.precio_compra)


